llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Fludarabine, a 2-fluoroadenine nucleoside closely related to the query, showed dose-independent systemic availability of approximately 55% after oral tablets in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Fludarabine monophosphate, the water-soluble prodrug of fludarabine, had an absolute oral bioavailability of 70% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Clofarabine, a 2-chloro-2'-fluoro-2'-deoxyadenosine analogue, had an absolute oral bioavailability of 49% in patients with solid tumours.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Cladribine, a 2-chlorodeoxyadenosine analogue, had an oral bioavailability of about 50% in humans.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 2-fluoroadenine nucleoside analogue; the closest experimental analogues (fludarabine, fludarabine monophosphate, clofarabine, cladribine) all show oral bioavailability above 20%, supporting a high prediction.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query.",
    "The query's sugar differs from fludarabine by having an anomeric hydroxyl and lacking the CH2OH group, which could alter absorption.",
    "Most evidence is from patients with haematological malignancies, not healthy subjects."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

